using Microsoft.Extensions.Caching.Distributed;

public class PostService
{
    private readonly BlogContext _db;
    private readonly IDistributedCache _cache;

    public PostService(BlogContext db, IDistributedCache cache)
    {
        _db = db;
        _cache = cache;
    }

    public async Task<List<Post>> GetTopPostsAsync()
    {
        var cached = await _cache.GetStringAsync("top-posts");
        if (cached is not null)
            return System.Text.Json.JsonSerializer.Deserialize<List<Post>>(cached)!;

        var posts = await _db.Posts.OrderByDescending(p => p.PublishedAt).Take(10).ToListAsync();
        var json = System.Text.Json.JsonSerializer.Serialize(posts);
        await _cache.SetStringAsync("top-posts", json, new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
        });
        return posts;
    }
}
